import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const { checkCompatibility, versionsFromManifest } = await import(
	"../scripts/check-component-compat.mjs"
);

const base = () => ({
	backend: { component: "backend", apiVersion: "1.0.0", accepts: { frontend: ">=1.0.0 <2.0.0", runner: ">=1.0.0 <2.0.0" } },
	frontend: { component: "frontend", apiVersion: "1.0.0", requires: { backendApi: ">=1.0.0 <2.0.0" } },
	runner: { component: "runner", apiVersion: "1.0.0", requires: { backendApi: ">=1.0.0 <2.0.0" } },
});

describe("checkCompatibility", () => {
	it("passes the shipped 1.0.0 files with four OK pairs", () => {
		const r = checkCompatibility(base());
		assert.equal(r.ok, true);
		assert.equal(r.lines.length, 4);
		assert.match(r.lines[0], /^OK frontend->backend: backend 1\.0\.0 satisfies /);
	});

	it("fails a 2.0.0 backend against <2.0.0 ranges with the exact message shape", () => {
		const v = base();
		v.backend.apiVersion = "2.0.0";
		const r = checkCompatibility(v);
		assert.equal(r.ok, false);
		assert.ok(r.failures.some((f) => f === "INCOMPATIBLE frontend->backend: backend 2.0.0 does not satisfy >=1.0.0 <2.0.0"));
		assert.ok(r.failures.some((f) => f.startsWith("INCOMPATIBLE runner->backend:")));
	});

	it("fails a non-semver apiVersion naming the component", () => {
		const v = base();
		v.runner.apiVersion = "v1";
		const r = checkCompatibility(v);
		assert.equal(r.ok, false);
		assert.ok(r.failures.some((f) => f.includes("runner") && f.includes('"v1"')));
	});

	it("checks a recorded manifest the same way", () => {
		const manifest = {
			components: {
				backend: { apiVersion: "1.0.0" },
				frontend: { apiVersion: "1.0.0", requiresBackendApi: ">=1.0.0 <2.0.0" },
				runner: { apiVersion: "1.0.0", requiresBackendApi: ">=1.0.0 <2.0.0" },
			},
		};
		assert.equal(checkCompatibility(versionsFromManifest(manifest), { manifestMode: true }).ok, true);
		manifest.components.backend.apiVersion = "2.0.0";
		const bad = checkCompatibility(versionsFromManifest(manifest), { manifestMode: true });
		assert.equal(bad.ok, false);
		assert.ok(bad.failures.some((f) => f.startsWith("INCOMPATIBLE frontend->backend: backend 2.0.0")));
	});
});

describe("check-component-compat CLI", () => {
	it("exits 0 on the shipped tree and 1 on a bumped backend", () => {
		const ok = spawnSync("node", ["scripts/check-component-compat.mjs"], { cwd: ROOT, encoding: "utf8" });
		assert.equal(ok.status, 0, ok.stderr);
		assert.match(ok.stdout, /OK frontend->backend/);

		const dir = fs.mkdtempSync(path.join(os.tmpdir(), "compat-"));
		for (const c of ["api", "frontend", "runner"]) {
			fs.mkdirSync(path.join(dir, c), { recursive: true });
			fs.copyFileSync(path.join(ROOT, c, "version.json"), path.join(dir, c, "version.json"));
		}
		const bumped = JSON.parse(fs.readFileSync(path.join(dir, "api", "version.json"), "utf8"));
		bumped.apiVersion = "2.0.0";
		fs.writeFileSync(path.join(dir, "api", "version.json"), JSON.stringify(bumped));
		const bad = spawnSync("node", ["scripts/check-component-compat.mjs", "--versions-dir", dir], { cwd: ROOT, encoding: "utf8" });
		assert.equal(bad.status, 1);
		assert.match(bad.stderr + bad.stdout, /INCOMPATIBLE/);
	});
});

#!/usr/bin/env bash
# redeploy.sh — pull and restart one component, per component, on this host.
# Lives in ~/apps/kainbain/ beside docker-compose.yml (template committed at
# deploy/redeploy.sh; install once by hand). It never builds and never runs
# tests; publishing is publish.sh's job (AsymmetricUpdatesPlan DA5).
#
# Runner transport is deliberately boring: redeploy.sh --runner expects
# ./kainbain-runner-<shortsha>.tar.gz beside it (copy it from the publishing
# checkout's dist/ by whatever means you already use). Its sha256 is verified
# against ./release-manifest.json before anything changes.
#
#   ./redeploy.sh [--backend|--frontend|--runner|--all] [--tag <tag>]
#                 [--dry-run] [--check] [--init]
# Default is --all. --tag pins one component's tag (single-component only).
set -uo pipefail
cd "$(dirname "$0")"

COMPONENT="all"; TAG=""; DRY_RUN=0; CHECK=0; INIT=0
while [ $# -gt 0 ]; do
  case "$1" in
    --backend) COMPONENT="backend" ;;
    --frontend) COMPONENT="frontend" ;;
    --runner) COMPONENT="runner" ;;
    --all) COMPONENT="all" ;;
    --tag) shift; TAG="${1:-}" ;;
    --dry-run) DRY_RUN=1 ;;
    --check) CHECK=1 ;;
    --init) INIT=1 ;;
    *) echo "redeploy.sh: unknown argument: $1" >&2; exit 2 ;;
  esac
  shift
done
if [ -n "$TAG" ] && [ "$COMPONENT" != "backend" ] && [ "$COMPONENT" != "frontend" ]; then
  echo "redeploy.sh: --tag is only valid with a single --backend or --frontend flag" >&2; exit 2
fi

log() { echo "redeploy: $*"; }
# run echoes in dry-run, executes otherwise.
run() { if [ "$DRY_RUN" = "1" ]; then echo "would run: $*"; else echo "+ $*"; "$@"; fi; }
record() { # component old new result
  [ "$DRY_RUN" = "1" ] && return 0
  printf '%s %s %s -> %s %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$1" "$2" "$3" "$4" >> ./redeploy.log
}

get_env() { # key -> value (empty when absent)
  [ -f ./.env ] || return 0
  grep -E "^$1=" ./.env 2>/dev/null | head -1 | cut -d= -f2-
}
set_env() { # key value — targeted edit, preserves every other line byte-for-byte
  local key="$1" value="$2"
  if grep -qE "^${key}=" ./.env 2>/dev/null; then
    sed -i "s|^${key}=.*|${key}=${value}|" ./.env
  else
    printf '%s=%s\n' "$key" "$value" >> ./.env
  fi
}
unset_env() { sed -i "/^$1=/d" ./.env; }

manifest_get() { # component field
  node -e '
const fs = require("fs");
try {
  const m = JSON.parse(fs.readFileSync("./release-manifest.json", "utf8"));
  const v = m?.components?.[process.argv[1]]?.[process.argv[2]];
  if (v !== undefined && v !== null) console.log(v);
} catch {}' "$1" "$2"
}
manifest_commit() {
  node -e '
const fs = require("fs");
try { const m = JSON.parse(fs.readFileSync("./release-manifest.json", "utf8")); if (m.commit) console.log(m.commit); } catch {}'
}

compat_check() { # returns 0 ok/warned, 1 incompatible-when-checker-found
  local checker=""
  if [ -n "${KAINBAIN_REPO_DIR:-}" ] && [ -f "$KAINBAIN_REPO_DIR/scripts/check-component-compat.mjs" ]; then
    checker="$KAINBAIN_REPO_DIR/scripts/check-component-compat.mjs"
  fi
  if [ -z "$checker" ]; then
    echo "WARN: compat check skipped (checker not found)" >&2
    return 0
  fi
  if [ ! -f ./release-manifest.json ]; then
    echo "WARN: compat check skipped (no release-manifest.json)" >&2
    return 0
  fi
  node "$checker" --manifest ./release-manifest.json
}

health_poll() { # deploy.sh health_check budget: 30 attempts, 2s apart
  local attempts="${KAINBAIN_HEALTH_ATTEMPTS:-30}" delay="${KAINBAIN_HEALTH_DELAY:-2}"
  local port; port="$(get_env KAINBAIN_PORT | grep -E '^[0-9]+$' || true)"; port="${port:-3100}"
  local url="${KAINBAIN_HEALTH_URL:-http://localhost:$port/status}"
  local i
  for i in $(seq 1 "$attempts"); do
    if curl -sf "$url" >/dev/null 2>&1; then return 0; fi
    sleep "$delay"
  done
  return 1
}

