    frontend: { apiVersion: "1.0.0", image: f.image, tag: f.tag, requiresBackendApi: ">=1.0.0 <2.0.0" },
    runner: { apiVersion: "1.0.0", requiresBackendApi: ">=1.0.0 <2.0.0" },
